package app.simple;
import android.app.*;import android.os.*;import android.content.*;import android.net.*;import android.view.*;import android.webkit.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;
public class MainActivity extends Activity {
 Store store;LinearLayout root,bar,body;WebView web;boolean continuous=false;String activeUrl="",resume="",cover="",rules="[]",engine="",jobText="";ValueCallback<Uri[]> upload;String picking="resume";ExecutorService worker=Executors.newSingleThreadExecutor();Handler handler=new Handler();Runnable loop;
 void toast(String s){runOnUiThread(()->Toast.makeText(this,s,Toast.LENGTH_LONG).show());}
 interface Work{void run()throws Exception;}
 void background(Work w){worker.execute(()->{try{w.run();}catch(Exception e){toast(e.getMessage()==null?"Operation failed":e.getMessage());}});}
 public void onCreate(Bundle b){super.onCreate(b);store=new Store(this);try{engine=asset("engine.js");JSONArray r=new JSONArray();for(String name:getAssets().list("rules"))r.put(new JSONObject(asset("rules/"+name)));rules=r.toString();}catch(Exception e){toast("Cannot load autofill engine");}home();handle(getIntent());}
 protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);handle(i);}
 void handle(Intent i){if(Intent.ACTION_SEND.equals(i.getAction())){String text=i.getStringExtra(Intent.EXTRA_TEXT);if(text!=null){java.util.regex.Matcher m=java.util.regex.Pattern.compile("https://[^\\s<>]+").matcher(text);if(m.find())open(m.group());else toast("Share an HTTPS application link");}}}
 String asset(String p)throws IOException{try(InputStream in=getAssets().open(p)){return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}
 void layout(String title){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,24,20,12);root.setBackgroundColor(0xffedf4ff);setContentView(root);TextView h=new TextView(this);h.setText(title);h.setTextSize(25);h.setTextColor(0xff173b73);root.addView(h);bar=new LinearLayout(this);bar.setOrientation(0);root.addView(bar);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
 void text(String s){TextView t=new TextView(this);t.setText(s);t.setTextSize(16);t.setPadding(0,12,0,12);body.addView(t);}
 void button(String title,Runnable action){Button b=new Button(this);b.setText(title);body.addView(b);b.setOnClickListener(v->action.run());}
 EditText edit(String hint,String value,boolean multi){EditText e=new EditText(this);e.setHint(hint);e.setText(value);e.setSingleLine(!multi);if(multi)e.setMinLines(3);body.addView(e);return e;}
 void home(){stopLoop();layout("Simple 🌱");text("Your application, with less repetition. Share a link from Chrome to begin.");EditText link=edit("Paste an HTTPS job or application link","",false);button("Open application",()->open(link.getText().toString()));button("Profile & saved answers",this::profile);button("Documents",this::documents);button("Applications",this::tracker);button("Account & sync",this::account);}
 void profile(){layout("Profile & answers");button("← Home",this::home);text("Save only answers you want reused. Work authorization and demographic fields stay blank unless explicitly entered. Review every filled application.");JSONObject data=store.read();JSONObject p=data.optJSONObject("profile");if(p==null)p=new JSONObject();java.util.Map<String,EditText> inputs=new java.util.LinkedHashMap<>();try{JSONArray rr=new JSONArray(rules);for(int i=0;i<rr.length();i++){JSONObject rule=rr.getJSONObject(i);String key=rule.getString("key");if(!key.contains("."))inputs.put(key,edit(rule.getJSONArray("aliases").getString(0),p.optString(key),false));}}catch(Exception e){toast("Profile schema error");}
 Entries work=new Entries(this,body,"Work history",data.optJSONArray("work"),new String[]{"company","title","location","start","end","description","current"});Entries education=new Entries(this,body,"Education",data.optJSONArray("education"),new String[]{"school","degree","field","start","end","gpa"});
 text("Saved answers: exact question → your saved answer. Questions are normalized for case and punctuation, never semantically guessed.");Answers answers=new Answers(this,body,data.optJSONObject("answers"));
 button("Save profile",()->{try{JSONObject profile=new JSONObject();for(String key:inputs.keySet()){String value=inputs.get(key).getText().toString().trim();if(!value.isEmpty())profile.put(key,value);}JSONObject normalized=answers.read();JSONObject latest=store.read();latest.put("profile",profile).put("work",work.read()).put("education",education.read()).put("answers",normalized);store.save(latest);toast("Profile saved on device");}catch(Exception e){toast("Profile could not be saved: "+e.getMessage());}});}
 void documents(){layout("Documents");button("← Home",this::home);JSONObject d=store.read();text("Select PDF or DOCX. Scanned PDFs use on-device OCR. Documents stay in private app storage.");button("Select résumé",()->pick("resume"));button("Select cover letter file",()->pick("cover"));EditText resumeText=edit("Résumé text (extracted or pasted)",d.optString("resumeText"),true);EditText coverText=edit("Cover letter text",d.optJSONObject("profile")==null?"":d.optJSONObject("profile").optString("coverText"),true);button("Save text",()->{try{JSONObject latest=store.read(),p=latest.optJSONObject("profile");if(p==null)p=new JSONObject();p.put("coverText",coverText.getText().toString());latest.put("profile",p).put("resumeText",resumeText.getText().toString());store.save(latest);toast("Saved");}catch(Exception e){toast("Save failed");}});EditText job=edit("Paste job description",jobText,true);button("Compare keywords",()->new AlertDialog.Builder(this).setTitle("Résumé keywords").setMessage(Keywords.compare(resumeText.getText().toString(),job.getText().toString())).setPositiveButton("Done",null).show());}
 void pick(String kind){picking=kind;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","application/vnd.openxmlformats-officedocument.wordprocessingml.document"});startActivityForResult(i,10);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==10&&result==RESULT_OK&&data!=null){String kind=picking;Uri u=data.getData();background(()->{File f=Documents.copy(this,u,kind);String parsed=Documents.extract(this,f);JSONObject latest=store.read();latest.put(kind+"File",f.getName());if(kind.equals("resume"))latest.put("resumeText",parsed);else{JSONObject p=latest.optJSONObject("profile");if(p==null)p=new JSONObject();p.put("coverText",parsed);latest.put("profile",p);}store.save(latest);runOnUiThread(this::documents);});}else if(request==20){if(upload!=null){upload.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));upload=null;}}}
 void stopLoop(){continuous=false;if(loop!=null)handler.removeCallbacks(loop);if(web!=null){web.destroy();web=null;}}
 void open(String url){Uri u=Uri.parse(url.trim());if(!"https".equals(u.getScheme())||u.getHost()==null){toast("Use a valid HTTPS link");return;}stopLoop();activeUrl=url.trim();layout("Application");button("← Home",this::home);button("Fill application",()->{continuous=true;fill();schedule();});button("Pause autofill",()->{continuous=false;toast("Autofill paused");});button("Use page as job description",()->web.evaluateJavascript("document.body.innerText",s->{try{jobText=new JSONArray("["+s+"]").getString(0);toast("Job description captured; open Documents to compare");}catch(Exception e){toast("Could not read page");}}));text("Review all answers and submit yourself. Employer logins stay in their portal. Attachments require your confirmation.");
 web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,3));web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(true);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
 web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !"https".equals(r.getUrl().getScheme());}public void onPageFinished(WebView v,String url){if(continuous)fill();}});
 web.setWebChromeClient(new WebChromeClient(){public boolean onShowFileChooser(WebView w,ValueCallback<Uri[]> cb,FileChooserParams p){if(upload!=null)upload.onReceiveValue(null);upload=cb;JSONObject d=store.read();new AlertDialog.Builder(MainActivity.this).setTitle("Choose attachment for this field").setItems(new String[]{"Selected résumé","Selected cover letter","Choose another file"},(dialog,which)->{if(which==2){try{startActivityForResult(p.createIntent(),20);}catch(Exception e){upload.onReceiveValue(null);upload=null;}return;}String f=d.optString(which==0?"resumeFile":"coverFile");if(f.isEmpty()){toast("Select a document in Documents first");upload.onReceiveValue(null);}else upload.onReceiveValue(new Uri[]{Uri.parse("content://app.simple.documents/"+f)});upload=null;}).setOnCancelListener(dialog->{if(upload!=null)upload.onReceiveValue(null);upload=null;}).show();return true;}});web.loadUrl(activeUrl);}
 void fill(){if(web==null)return;String js=engine+";SimpleEngine.fill("+store.read()+","+rules+");";web.evaluateJavascript(js,null);}
 void schedule(){if(loop!=null)handler.removeCallbacks(loop);loop=()->{if(!continuous||web==null)return;fill();web.evaluateJavascript("SimpleEngine.confirmed()",s->{if("true".equals(s)){try{store.track(activeUrl,web.getTitle());toast("Submission confirmation recorded");continuous=false;}catch(Exception e){toast("Tracker save failed");}}});if(continuous)handler.postDelayed(loop,1500);};handler.postDelayed(loop,1500);}
 void tracker(){layout("Applications");button("← Home",this::home);JSONArray jobs=store.read().optJSONArray("jobs");if(jobs==null||jobs.length()==0)text("No supported submission confirmations detected yet. A filled form is not a submitted application.");else for(int i=0;i<jobs.length();i++){JSONObject j=jobs.optJSONObject(i);text(j.optString("title")+"\n"+j.optString("url")+"\n"+new java.util.Date(j.optLong("confirmedAt")));}}
 void account(){layout("Account & sync");button("← Home",this::home);text("Configure your Supabase project after applying the included migration. Only a public publishable/anon key belongs here. Never use a service-role key.");android.content.SharedPreferences prefs=getSharedPreferences("account",0);EditText url=edit("Supabase HTTPS URL",prefs.getString("url",""),false),key=edit("Public API key",prefs.getString("key",""),false),email=edit("Email","",false),password=edit("Password","",false);password.setInputType(129);
 button("Save project settings",()->{prefs.edit().putString("url",url.getText().toString().trim()).putString("key",key.getText().toString().trim()).apply();toast("Settings saved");});
 button("Create account",()->background(()->{Supabase.request(url.getText().toString().trim(),key.getText().toString().trim(),"","/auth/v1/signup","POST",new JSONObject().put("email",email.getText().toString()).put("password",password.getText().toString()));toast("Check your email to confirm, then sign in");}));
 button("Sign in",()->background(()->{JSONObject auth=Supabase.request(prefs.getString("url",""),prefs.getString("key",""),"","/auth/v1/token?grant_type=password","POST",new JSONObject().put("email",email.getText().toString()).put("password",password.getText().toString()));Secrets.save(this,auth.getString("access_token"));prefs.edit().putString("user",auth.getJSONObject("user").getString("id")).apply();toast("Signed in");}));
 button("Upload profile & tracker",()->background(()->{String token=Secrets.read(this);if(token.isEmpty())throw new IOException("Sign in first");CloudDocuments.sync(this,prefs.getString("url",""),prefs.getString("key",""),token,prefs.getString("user",""),store.read(),false);Supabase.request(prefs.getString("url",""),prefs.getString("key",""),token,"/rest/v1/profiles?on_conflict=user_id","POST",new JSONObject().put("user_id",prefs.getString("user","")).put("data",store.read()));toast("Uploaded profile");}));
 button("Restore profile from cloud",()->new AlertDialog.Builder(this).setMessage("Replace the profile and tracker on this device with the cloud copy?").setNegativeButton("Cancel",null).setPositiveButton("Restore",(a,b)->background(()->{JSONObject result=Supabase.request(prefs.getString("url",""),prefs.getString("key",""),Secrets.read(this),"/rest/v1/profiles?select=data&user_id=eq."+prefs.getString("user",""),"GET",null);JSONArray rows=result.getJSONArray("rows");if(rows.length()!=1)throw new IOException("No saved cloud profile");JSONObject restored=rows.getJSONObject(0).getJSONObject("data");CloudDocuments.sync(this,prefs.getString("url",""),prefs.getString("key",""),Secrets.read(this),prefs.getString("user",""),restored,true);store.save(restored);toast("Restored");})).show());button("Sign out",()->{Secrets.clear(this);prefs.edit().remove("user").apply();toast("Signed out on this device");});}
 protected void onDestroy(){stopLoop();worker.shutdown();super.onDestroy();}
 public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else home();}
}
